<section class="mt-7"><h2 class="text-xl font-extrabold">White-label portal</h2><p class="text-sm text-[#78908c]">Your customers and team see this identity on verified custom domains.</p><div class="mt-6 grid gap-5 xl:grid-cols-2"><form action="<?= base_url('reseller/branding') ?>" method="post" enctype="multipart/form-data" class="card space-y-4 p-6"><?= csrf_field() ?><h3 class="font-extrabold">Brand appearance</h3><label class="block text-xs font-bold">Brand name<input name="brand_name" required value="<?= esc($profile['brand_name']??'') ?>" class="field mt-2"></label><label class="block text-xs font-bold">Support email<input name="support_email" type="email" value="<?= esc($profile['support_email']??'') ?>" class="field mt-2"></label><div class="grid grid-cols-2 gap-3"><label class="text-xs font-bold">Primary color<input name="primary_color" type="color" value="<?= esc($profile['primary_color']??'#44B89D') ?>" class="field mt-2 h-12"></label><label class="text-xs font-bold">Secondary color<input name="secondary_color" type="color" value="<?= esc($profile['secondary_color']??'#288DA5') ?>" class="field mt-2 h-12"></label></div><label class="block text-xs font-bold">Logo<input name="logo" type="file" accept=".png,.jpg,.jpeg,.webp,.svg" class="field mt-2 text-sm"></label><label class="block text-xs font-bold">Favicon<input name="favicon" type="file" accept=".png,.ico,.svg" class="field mt-2 text-sm"></label><button class="btn btn-primary">Save branding</button></form><section class="card p-6"><h3 class="font-extrabold">Custom domains</h3><p class="mt-1 text-sm text-[#78908c]">Add the hostname, then create a CNAME pointing it to the configured platform target.</p><form action="<?= base_url('reseller/domain') ?>" method="post" class="mt-4 flex gap-2"><?= csrf_field() ?><input name="domain" required class="field" placeholder="mail.yourbrand.com"><button class="btn btn-primary">Add</button></form><div class="mt-5 space-y-3"><?php foreach($domains as $domain): ?><div class="rounded-xl bg-[#e7f2ef] p-4"><div class="flex justify-between"><p class="font-bold"><?= esc($domain['domain']) ?></p><span class="text-xs font-bold uppercase text-sea"><?= esc($domain['status']) ?></span></div><p class="mt-2 text-xs text-[#78908c]">CNAME → <?= esc((string)env('app.cnameTarget','not configured')) ?></p><?php if($domain['status']!=='verified'): ?><form action="<?= base_url('reseller/domain/'.$domain['id'].'/verify') ?>" method="post" class="mt-3"><?= csrf_field() ?><button class="btn bg-white text-sea shadow-soft">Verify DNS</button></form><?php endif ?></div><?php endforeach ?><?php if(!$domains): ?><p class="rounded-xl bg-[#e7f2ef] p-4 text-sm text-[#78908c]">No custom domain added yet.</p><?php endif ?></div></section></div></section>
